// What the ac-* blocks of this site share: the design system package (@ac-brandsframework/eds-
// assets,
// installed in /ds-eds-assets by `npx eds-assets-install --to ds-eds-assets`), its CSS loader, and
// the
// steps every block takes to read its authored rows and hand them to a design-system render
// wrapper.
//
// A block's fields are this site's model (blocks/<block>/_<block>.json);
// blocks/<block>/<block>-fields.js
// (generated by tools/ds-blocks/generate.mjs from the package's contracts/field-contract.json) says
// which
// field fills which content prop or option list of the wrapper.
import { loadBundle as loadDsBundle } from '../ds-eds-assets/js/vendor/ds-bundles.js';
import {
  blockRows, fieldsByName, valuesByName, editorAttributes, instrumentationOf,
} from '../ds-eds-assets/js/vendor/field-rows.js';
import { componentInput, renderComponentBlock } from '../ds-eds-assets/js/vendor/component-block.js';
import { moveInstrumentation } from '../ds-eds-assets/js/vendor/move-instrumentation.js';
import { dropHidden } from '../ds-eds-assets/js/vendor/model-conditions.js';

// The folder the package is installed in, relative to the site root (window.hlx.codeBasePath).
export const ASSETS = 'ds-eds-assets';

/**
 * Loads a CSS bundle of the package (its parts, in the package's order).
 * @param {string} file a bundle name, with or without .css
 */
export const loadBundle = (file) => loadDsBundle(file, ASSETS);

// The fields every ac-* block has besides its design-system fields: the name of the container it is
// nested into (any block), and the name a container gives itself (ac-container).
export const NEST_FIELDS = ['parentId', 'nestId'];

const nameOf = (row) => row.children[0]?.textContent.trim();

/**
 * Reads the nesting fields of a block (parentId, nestId) into its data attributes, which
 * ds-eds-assets/js/vendor/nest-by-parent.js reads, and removes their rows.
 * @param {HTMLElement} block
 * @param {Element[]} rows the block's rows; the nesting rows are removed from it
 */
export function applyNesting(block, rows) {
  NEST_FIELDS.forEach((name) => {
    const index = rows.findIndex((row) => row.children.length === 2 && nameOf(row) === name);
    if (index < 0) return;
    const value = rows[index].children[1].textContent.trim();
    if (value) block.dataset[name] = value;
    rows[index].remove();
    rows.splice(index, 1);
  });
}

/**
 * The rows of a block: its own key-value rows (two cells, the first one of `names`) and the rows of
 * its items (a container block's children, one row per item, one cell per item field).
 * @param {HTMLElement} block
 * @param {string[]} names the block's own field names
 */
export function readBlock(block, names) {
  // A block the editor instruments itself holds its rows directly. blockRows takes a first child
  // with an editor resource for an inner wrapper of the rows, which in a container block (list,
  // accordion, table of contents layout) is its first item: the items would be read as that item's
  // cells, and the first item's resource would move onto the rendered block.
  const { rows, wrapper } = block.hasAttribute('data-aue-resource')
    ? { rows: [...block.children], wrapper: null }
    : blockRows(block);
  applyNesting(block, rows);
  const own = rows.filter((row) => row.children.length === 2 && names.includes(nameOf(row)));
  const items = rows.filter((row) => !own.includes(row));
  return { own, items, wrapper };
}

/**
 * Puts the rendered element in the block, with the editor's attributes of the block's wrapper
 * on it.
 * @param {HTMLElement} block
 * @param {HTMLElement | undefined} root
 * @param {Element | null} wrapper
 */
export function replaceBlock(block, root, wrapper) {
  block.textContent = '';
  if (!root) return;
  if (wrapper) moveInstrumentation(wrapper, root);
  block.append(root);
}

// ---- The None choice ---------------------------------------------------------------------------

// The value of the "None" choice every select of the models starts with (tools/ds-blocks/
// generate.mjs): the field adds nothing.
export const NONE = '_none';

// An option value without the None choice: '' for a single value, the other values for several.
function withoutNone(value) {
  if (typeof value !== 'string' || !value.includes(NONE)) return value;
  return value.split(',').map((v) => v.trim()).filter((v) => v && v !== NONE).join(',');
}

/** Content props without the None choice: a prop chosen as None is left out. */
function contentWithoutNone(content) {
  return Object.fromEntries(Object.entries(content).filter(([, v]) => v !== NONE));
}

/**
 * Options without the None choice. A class list chosen as None is given empty: it adds no class
 * and replaces the wrapper's default (a card's theme). A list the wrapper takes as a prop is left
 * out, so the component's own default applies.
 * @param {Record<string, any>} options
 * @param {string[]} [propLists]
 */
function optionsWithoutNone(options, propLists = []) {
  return Object.fromEntries(Object.entries(options).flatMap(([list, value]) => {
    const clean = withoutNone(value);
    if (clean === value) return [[list, value]];
    if (!clean && propLists.includes(list)) return [];
    return [[list, clean]];
  }));
}

/**
 * The design system's input with the None choices applied (see NONE): the block's content props
 * and options, and its items' when it has items.
 * @param {{ content?: object, options?: object }} input
 * @param {object} fields the block's <block>-fields.js
 */
export function applyNone(input, fields) {
  const content = contentWithoutNone(input.content || {});
  if (Array.isArray(content.items)) {
    content.items = content.items.map((item) => {
      const clean = contentWithoutNone(item);
      if (clean.options) clean.options = optionsWithoutNone(clean.options, fields.ITEM_PROP_LISTS);
      return clean;
    });
  }
  return {
    ...input,
    content,
    options: optionsWithoutNone(input.options || {}, fields.PROP_LISTS),
  };
}

/**
 * Removes the section fields chosen as None (grid, spacing, layout) before the sections are
 * decorated, so they add nothing.
 * @param {Element} main
 */
export function clearNoneSectionFields(main) {
  main.querySelectorAll(':scope > .section').forEach((section) => {
    Object.keys(section.dataset).forEach((key) => {
      if (section.dataset[key] === NONE) delete section.dataset[key];
    });
  });
}

/**
 * Decorates a block of one design-system component: reads its rows by the field table in its
 * <block>-fields.js, renders the component with `render` and loads the block's own bundle.
 * @param {HTMLElement} block
 * @param {{ bundle: string, render: Function, fields: object }} config
 */
export function decorateComponentBlock(block, { bundle, render, fields }) {
  loadBundle(bundle);
  const { own, wrapper } = readBlock(block, fields.NAMES);
  const root = renderComponentBlock(own, {
    render: (input) => render({ ...applyNone(input, fields), loadBundle }),
    names: fields.NAMES,
    kinds: fields.KINDS,
    contentFields: fields.CONTENT_FIELDS,
    optionFields: fields.OPTION_FIELDS,
    conditions: fields.FIELD_CONDITIONS,
    editableProps: fields.EDITABLE_PROPS,
  });
  replaceBlock(block, root, wrapper);
  return root;
}

/**
 * The design-system input of a container block (accordion, tabs, list, carousels): its own fields,
 * and `content.items` built from its item rows by the item field table, with the editor's
 * attributes of each item (`items.<n>`) and of each of its editable fields (`items.<n>.<prop>`).
 * An item's option fields (ITEM_OPTION_FIELDS) go into the item's `options`, without those the
 * model hides for the item's type (ITEM_FIELD_CONDITIONS). A title cell that holds a heading gives
 * the item's `titleTag` (the editor folds titleType into the title).
 * @param {Element[]} own the block's key-value rows
 * @param {Element[]} items the item rows
 * @param {object} fields the block's <block>-fields.js
 */
export function containerInput(own, items, fields) {
  const ownFields = fieldsByName(own, fields.NAMES);
  const input = componentInput(ownFields, valuesByName(ownFields, fields.KINDS), {
    contentFields: fields.CONTENT_FIELDS,
    optionFields: fields.OPTION_FIELDS,
    editableProps: [],
  });
  const contentFields = fields.ITEM_CONTENT_FIELDS;
  const optionFields = fields.ITEM_OPTION_FIELDS || {};
  const fieldOf = (path) => Object.keys(contentFields).find((f) => contentFields[f] === path);
  const titleField = fieldOf('title');
  const levelField = fieldOf('titleTag');
  const editable = {};
  input.content.items = items.map((row, index) => {
    // An item row holds one cell per field, in model order.
    const itemFields = Object.fromEntries(fields.ITEM_NAMES
      .map((name, i) => [name, { row: row.children[i], cell: row.children[i] }]));
    const stored = valuesByName(itemFields, fields.ITEM_KINDS);
    const heading = titleField && itemFields[titleField]?.cell?.querySelector(':scope > h1, :scope > h2, :scope > h3, :scope > h4, :scope > h5');
    if (levelField && heading) stored[levelField] = heading.tagName.toLowerCase();
    const shown = dropHidden(stored, fields.ITEM_FIELD_CONDITIONS || {});
    const values = Object.fromEntries(Object.entries(stored)
      .filter(([name]) => !(name in optionFields) || name in shown));
    const item = componentInput(itemFields, values, {
      contentFields,
      optionFields,
      editableProps: fields.ITEM_EDITABLE_PROPS,
    });
    const itemAttributes = instrumentationOf(row);
    if (itemAttributes) editable[`items.${index}`] = itemAttributes;
    Object.entries(item.editable).forEach(([prop, attributes]) => {
      editable[`items.${index}.${prop}`] = attributes;
    });
    // A None choice is applied by applyNone, which the container block calls on this input.
    const itemOptions = Object.fromEntries(Object.entries(item.options)
      .filter(([, v]) => v !== undefined));
    return {
      ...item.content,
      ...(Object.keys(itemOptions).length && { options: itemOptions }),
    };
  });
  input.editable = editable;
  return applyNone(input, fields);
}

export { editorAttributes, moveInstrumentation };

// The ac-* blocks of this site, and the selector of those that may be nested into a container
// (a block that names one in its "Nest inside" field carries data-parent-id).
export const DS_BLOCKS = [
  'ac-accordion', 'ac-banner', 'ac-button', 'ac-card', 'ac-carousel', 'ac-container', 'ac-download',
  'ac-embed-iframe', 'ac-embed-video', 'ac-image', 'ac-link', 'ac-list', 'ac-separator',
  'ac-splide-carousel', 'ac-table', 'ac-tabs', 'ac-text', 'ac-text-content', 'ac-title',
];
export const NESTABLE_SELECTOR = DS_BLOCKS.map((name) => `.block.${name}[data-parent-id]`).join(',');
// The models of the blocks that hold nested blocks.
export const LAYOUT_MODELS = ['ac-container'];
